/**
 * retrieval-bench.mjs
 * ------------------------------------------------------------
 * Measures what retrieval costs against what a full catalog scan costs, at
 * 650 / 1,000 / 3,500 / 10,000 / 100,000 scenarios.
 *
 * Run: node bench/retrieval-bench.mjs
 *
 * The catalogs are generated by catalog-generator.mjs, which reproduces the
 * shipped catalog's sharing structure — a 7.7% head fanout and a power-law
 * tail — rather than handing out 100,000 unique tokens. That distinction is
 * the difference between a measurement and a press release: retrieval looks
 * free on a catalog with no shared tokens, and no real catalog looks like
 * that.
 *
 * Messages are drawn from the catalog's own token distribution, so a benchmark
 * message is as likely to contain a common token as a real one is. Three
 * message shapes are measured separately, because they have genuinely
 * different costs and averaging them would hide the one that matters:
 *
 *   typical    3 tokens drawn by frequency — what most customers send
 *   specific   3 rare tokens               — the best case
 *   common     3 of the most shared tokens — the WORST case, and the one that
 *                                            decides whether this scales
 */
import { generateCatalog } from './catalog-generator.mjs';
import { buildScenarioIndex, indexStats } from '../sie/retrieval/scenario-index.js';
import { retrieveCandidates } from '../sie/retrieval/candidate-retrieval.js';
import { computeScenarioConfidence } from '../sie/diagnostics/hypothesis-tracker.js';

const SIZES = [650, 1000, 3500, 10000, 100000];
const ITERATIONS = 200;

function fullScan(scenarios, presences) {
    const out = [];
    for (const scenario of scenarios) {
        const { confidence } = computeScenarioConfidence(scenario, presences);
        if (confidence > 0) out.push({ id: scenario.id, confidence });
    }
    out.sort((a, b) => (b.confidence - a.confidence) || String(a.id).localeCompare(String(b.id)));
    return out;
}

function time(fn, iterations) {
    fn(); fn(); fn();                       // warm the JIT
    const t0 = process.hrtime.bigint();
    for (let i = 0; i < iterations; i++) fn();
    return Number(process.hrtime.bigint() - t0) / 1e6 / iterations;
}

function messages(index, rand) {
    const byFrequency = [...index.postings.entries()].sort((a, b) => b[1].ids.length - a[1].ids.length);
    const common = byFrequency.slice(0, 12).map(([t]) => t);
    const rare = byFrequency.slice(-Math.max(12, byFrequency.length >> 2)).map(([t]) => t);
    const weighted = [];
    for (const [token, list] of byFrequency) for (let i = 0; i < Math.min(list.ids.length, 40); i++) weighted.push(token);

    const pick = (pool, n) => {
        const m = new Map();
        for (let i = 0; i < n; i++) m.set(pool[Math.floor(rand() * pool.length)], 1);
        return m;
    };
    return {
        typical: pick(weighted, 3),
        specific: pick(rare, 3),
        common: pick(common, 3)
    };
}

let rngState = 12345;
const rand = () => { rngState = (rngState * 1664525 + 1013904223) >>> 0; return rngState / 4294967296; };

console.log('SIE retrieval scalability — measured, not projected');
console.log(`node ${process.version}, ${ITERATIONS} iterations per cell\n`);

const rows = [];
for (const size of SIZES) {
    const { scenarios, stats } = generateCatalog(size, { seed: 42 });
    const index = buildScenarioIndex(scenarios);
    const istats = indexStats(index);
    const msgs = messages(index, rand);

    const buildMs = (() => {
        const copy = scenarios.map((s) => s);   // a fresh array => a fresh index
        const t0 = process.hrtime.bigint();
        buildScenarioIndex(copy);
        return Number(process.hrtime.bigint() - t0) / 1e6;
    })();

    for (const [shape, presences] of Object.entries(msgs)) {
        const scanMs = time(() => fullScan(scenarios, presences), shape === 'common' ? 20 : ITERATIONS);
        const retrieveMs = time(() => retrieveCandidates(index, presences), ITERATIONS);
        const out = retrieveCandidates(index, presences);

        // The equivalence claim, re-checked at every size rather than assumed
        // to survive scale. A benchmark that stops being correct is not a
        // benchmark of anything.
        const expected = fullScan(scenarios, presences);
        const same = expected.length === out.considered &&
            expected.every((e, i) => out.candidates[i] && out.candidates[i].scenario.id === e.id);

        rows.push({
            size, shape,
            scanMs, retrieveMs,
            speedup: scanMs / retrieveMs,
            scanned: out.scanned,
            considered: out.considered,
            scannedPct: (100 * out.scanned) / size,
            equivalent: same,
            buildMs, istats, stats
        });
    }
}

const head = ['N', 'message', 'scan ms', 'retrieve ms', 'speedup', 'posts read', '% of N', 'candidates', 'exact'];
const widths = [8, 9, 9, 12, 9, 11, 8, 11, 6];
console.log(head.map((h, i) => h.padEnd(widths[i])).join(''));
console.log('-'.repeat(widths.reduce((a, b) => a + b, 0)));
for (const r of rows) {
    console.log([
        String(r.size), r.shape, r.scanMs.toFixed(3), r.retrieveMs.toFixed(4),
        `${r.speedup.toFixed(0)}x`, String(r.scanned), `${r.scannedPct.toFixed(2)}%`,
        String(r.considered), r.equivalent ? 'yes' : 'NO'
    ].map((c, i) => c.padEnd(widths[i])).join(''));
}

console.log('\nIndex, per catalog size:');
console.log('N         vocab     postings   avg len   max len   head fanout   build ms   collisions');
const seen = new Set();
for (const r of rows) {
    if (seen.has(r.size)) continue;
    seen.add(r.size);
    console.log([
        String(r.size).padEnd(10), String(r.istats.vocabulary).padEnd(10),
        String(r.istats.postingsTotal).padEnd(11), r.istats.averagePostingLength.toFixed(2).padEnd(10),
        String(r.istats.longestPostingLength).padEnd(10),
        `${(100 * r.istats.worstCaseFanout).toFixed(2)}%`.padEnd(14),
        r.buildMs.toFixed(1).padEnd(11),
        `${r.stats.collisions} (${(100 * r.stats.collisionRate).toFixed(2)}%)`
    ].join(''));
    if (r.stats.shapeWarning) console.log(`          WARNING: ${r.stats.shapeWarning}`);
}

const broken = rows.filter((r) => !r.equivalent);
console.log(broken.length === 0
    ? '\nEquivalence with a full scan held at every size and every message shape.'
    : `\nEQUIVALENCE BROKEN in ${broken.length} cell(s): ${broken.map((r) => `${r.size}/${r.shape}`).join(', ')}`);

// ------------------------------------------------------------
// The two numbers the table above does not show, and which decide whether
// 100,000 is actually reachable: the true worst case, and memory.
//
// The "common" row uses three of the twelve most-shared tokens, which is a
// realistic bad message. The true upper bound is a message consisting of
// nothing but the single hottest token — every posting for it must be read.
//
// Memory is measured with --expose-gc when available, because the catalog and
// its index are RESIDENT: this engine holds them in the isolate, and an edge
// runtime's memory ceiling is a harder limit than its CPU budget.

console.log('\nUpper bound and footprint:');
const gc = typeof global.gc === 'function' ? global.gc : null;
if (!gc) console.log('  (run with --expose-gc for memory figures)');
console.log('N         hottest token        postings   worst ms   index MB   catalog MB   build ms');
for (const size of SIZES) {
    if (gc) gc();
    const before = process.memoryUsage().heapUsed;
    const { scenarios } = generateCatalog(size, { seed: 42 });
    if (gc) gc();
    const afterCatalog = process.memoryUsage().heapUsed;
    const index = buildScenarioIndex(scenarios);
    if (gc) gc();
    const afterIndex = process.memoryUsage().heapUsed;

    const stats = indexStats(index);
    const presences = new Map([[stats.longestPostingToken, 1]]);
    const worstMs = time(() => retrieveCandidates(index, presences), 50);
    const out = retrieveCandidates(index, presences);

    const t0 = process.hrtime.bigint();
    buildScenarioIndex(scenarios.map((s) => s));
    const buildMs = Number(process.hrtime.bigint() - t0) / 1e6;

    console.log([
        String(size).padEnd(10), String(stats.longestPostingToken).padEnd(21),
        String(out.scanned).padEnd(11), worstMs.toFixed(3).padEnd(11),
        gc ? ((afterIndex - afterCatalog) / 1048576).toFixed(1).padEnd(11) : '-'.padEnd(11),
        gc ? ((afterCatalog - before) / 1048576).toFixed(1).padEnd(13) : '-'.padEnd(13),
        buildMs.toFixed(1)
    ].join(''));
}
